    def test_shared_secret_stability(self, qkd_lib, keypair):
        """Test that shared secret is stable across multiple decapsulations."""
        pk, sk = keypair
        ct = KyberCiphertext()
        ss_enc = KyberSharedSecret()
        
        qkd_lib.qkd_kyber_encaps(ctypes.byref(ct), ctypes.byref(ss_enc), ctypes.byref(pk))
        
        # Decapsulate multiple times
        for _ in range(10):
            ss_dec = KyberSharedSecret()
            qkd_lib.qkd_kyber_decaps(ctypes.byref(ss_dec), ctypes.byref(ct), ctypes.byref(sk))
            assert bytes(ss_enc.data) == bytes(ss_dec.data), "Shared secret should be stable"

    def test_ciphertext_integrity(self, qkd_lib, keypair):
        """Test that ciphertext is not corrupted during transmission."""
        pk, sk = keypair
        ct = KyberCiphertext()
        ss_enc = KyberSharedSecret()
        
        qkd_lib.qkd_kyber_encaps(ctypes.byref(ct), ctypes.byref(ss_enc), ctypes.byref(pk))
        
        # Corrupt ciphertext and verify decapsulation fails or produces different secret
        corrupted_ct = KyberCiphertext()
        corrupted_ct.data = ct.data
        corrupted_ct.data[0] ^= 0xFF  # Flip first byte
        
        ss_dec = KyberSharedSecret()
        result = qkd_lib.qkd_kyber_decaps(ctypes.byref(ss_dec), ctypes.byref(corrupted_ct), ctypes.byref(sk))
        assert result == 0, "Decapsulation should still succeed"
