class TestThreadSafety:
    """Tests for thread safety (requires pthread support)."""

    def test_concurrent_keypair_generation(self, qkd_lib):
        """Test concurrent keypair generation from multiple threads."""
        import threading
        
        errors = []
        results = []
        
        def generate_keypair():
            try:
                pk = KyberPublicKey()
                sk = KyberSecretKey()
                result = qkd_lib.qkd_kyber_keypair(ctypes.byref(pk), ctypes.byref(sk))
                if result != 0:
                    errors.append(f"Keypair generation failed: {result}")
                else:
                    results.append((bytes(pk.data), bytes(sk.data)))
            except Exception as e:
                errors.append(str(e))
        
        threads = [threading.Thread(target=generate_keypair) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        
        assert not errors, f"Thread errors: {errors}"
        assert len(results) == 10, "All threads should produce keypairs"
        
        # Verify all keypairs are identical (deterministic)
        assert len(set(results)) == 1, "All keypairs should be identical"

    def test_concurrent_encaps_decaps(self, qkd_lib, keypair):
        """Test concurrent encapsulation/decapsulation."""
        import threading
        
        pk, sk = keypair
        errors = []
        shared_secrets = []
        
        def perform_operation():
            try:
                ct = KyberCiphertext()
                ss_enc = KyberSharedSecret()
                ss_dec = KyberSharedSecret()
                
                result = qkd_lib.qkd_kyber_encaps(ctypes.byref(ct), ctypes.byref(ss_enc), ctypes.byref(pk))
                if result != 0:
                    errors.append(f"Encapsulation failed: {result}")
                    return
                
                result = qkd_lib.qkd_kyber_decaps(ctypes.byref(ss_dec), ctypes.byref(ct), ctypes.byref(sk))
                if result != 0:
                    errors.append(f"Decapsulation failed: {result}")
                    return
                
                if bytes(ss_enc.data) != bytes(ss_dec.data):
                    errors.append("Shared secrets do not match")
                else:
                    shared_secrets.append(bytes(ss_enc.data))
            except Exception as e:
                errors.append(str(e))
        
        threads = [threading.Thread(target=perform_operation) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        
        assert not errors, f"Thread errors: {errors}"
        assert len(shared_secrets) == 10, "All operations should succeed"
        assert len(set(shared_secrets)) == 10, "All shared secrets should be unique"

